sys_script_include.script:
gs.include("IllumioConstants");
var IllumioPollAsyncJobStatus = Class.create();
IllumioPollAsyncJobStatus.prototype = {

    initialize: function(asyncJobLocation, retryAfter, jobSysID, primaryKey, resultTable, keysToMap, retryCount, illumio_job_id, job_identifier, jobCreatedOn) {

        this.asyncJobLocation = asyncJobLocation;
        this.retryAfter = retryAfter;
        this.jobSysID = jobSysID;
        this.resultTable = resultTable;
        this.keysToMap = keysToMap;
        this.primaryKey = primaryKey;
        this.retryCount = retryCount;
        this.illumio_job_id = illumio_job_id;
        this.job_identifier = job_identifier;
        // Passed in from the Script Action's `current.sys_created_on` rather than re-queried here.
        // The caller already holds the async job record; reading it again would be one extra
        // query per poll to learn something it was looking at.
        this.jobCreatedOn = jobCreatedOn;
        this.logger = new IllumioLogger(illumio_job_id, 'IllumioPollAsyncJobStatus');
    },

    /**
     * '[Labels]' / '[Workloads]', matching the tag the MID side puts on its own lines.
     *
     * Without it a poll line cannot be told from the other async job's poll line -- the two run
     * concurrently and interleave in syslog, which is most of why the old HANDOFF line was
     * unreadable.
     *
     * @returns {String} Bracketed tag, or '' when the identifier is missing
     */
    _tag: function() {
        var identifier = this.job_identifier + "";
        if (gs.nil(identifier) || identifier === 'null' || identifier === 'undefined') {
            return '';
        }
        return '[' + identifier.charAt(0).toUpperCase() + identifier.slice(1) + '] ';
    },

    /**
     * How long this async job has been outstanding, and which poll this is.
     *
     * The poll ordinal is DERIVED from elapsed over the retry interval, not counted -- there is no
     * counter on x_illu2_illumio_illumio_pce_async_jobs and adding one is a dictionary change for
     * a log line. It is therefore approximate whenever the scheduler runs late, which is why the
     * elapsed figure is the one printed first and the ordinal reads as a rough position rather
     * than a guarantee.
     *
     * @returns {String} e.g. '93s elapsed, poll ~10'
     */
    _progress: function() {
        if (gs.nil(this.jobCreatedOn)) {
            return 'elapsed unknown';
        }

        var started = new GlideDateTime(this.jobCreatedOn + "");
        var elapsedSeconds = Math.round(
            (new GlideDateTime().getNumericValue() - started.getNumericValue()) / 1000);

        var interval = parseInt(this.retryAfter, 10);
        if (isNaN(interval) || interval <= 0) {
            return elapsedSeconds + 's elapsed';
        }

        return elapsedSeconds + 's elapsed, poll ~' + (Math.floor(elapsedSeconds / interval) + 1);
    },
    /**
     * Calls the MID server script include to poll the async job status
     */
    execute: function() {
        var utils = new IllumioUtils();
        var configSysId = utils.getConfigurationId(this.illumio_job_id);

        var pceConfig = new IllumioGetPCEConfiguration(this.illumio_job_id).getConfiguration(configSysId);

        if (pceConfig) {
            try {
                var parameters = {
                    illumio_pce_configuration_id: configSysId,
                    pce_url: pceConfig.pceUrl,
                    pce_endpoint: '/api/v2' + this.asyncJobLocation,
                    pce_authorization: gs.base64Encode(pceConfig.pceUsername + ':' + pceConfig.pceSecret),
                    pce_async_job_sys_id: this.jobSysID + '',
                    illumio_scheduled_job_id: this.illumio_job_id + '',
                    operation: 'get_async_job_status',
                    result_table_name: this.resultTable,
                    keys_to_map: this.keysToMap,
                    primary_key: this.primaryKey,
                    retry_count: this.retryCount,
                    job_identifier: this.job_identifier,
                    time_zone: gs.getSession().getTimeZoneName(),
                    enable_pce_mid_proxy: pceConfig.enable_pce_mid_proxy,
                    retry_params: JSON.stringify(pceConfig.retry_params),
                    // Was x_illu2_illumio.payload.batch.size, retired. See IllumioConstants.
                    chunk_size: BATCH_SIZE_STANDARD
                };

                // The line that replaces the HANDOFF repeat this call now suppresses. It says the
                // three things the old one could not: which async job, how long it has been
                // outstanding, and roughly which attempt this is. A PCE job that hangs is the
                // case this exists for -- "still waiting" is only useful with a number on it.
                this.logger.info(this._tag() + 'Checking fetch status (' + this._progress() + ')');

                // quiet: the HANDOFF line drops to debug for polls. See IllumioAddToECCQueue --
                // this is the only caller that passes it, and the only one that loops.
                var illumioAddToECCQueue = new IllumioAddToECCQueue('IllumioManageAsyncJobs',
                    pceConfig.midServer, parameters, { quiet: true });
                illumioAddToECCQueue.insert();

            } catch (exception) {
                this.logger.error('Exception occurred while preparing request data to poll status. Exception: ' + exception);
            }

        } else {
            this.logger.error('No configurations available');
        }
    },

    type: 'IllumioPollAsyncJobStatus'
};
